<?php

declare(strict_types=1);

namespace TreeshaInfotech\Vapi\Builders;

use Vapi\Files\Requests\CreateFileDto;
use Vapi\Utils\File;

/**
 * Fluent builder for CreateFileDto.
 *
 * Generated by `composer build:builders`. Do not edit; regenerate after
 * upgrading vapi/vapi.
 */
final readonly class CreateFileBuilder
{
    private function __construct(
        private File $file,
    ) {}

    public static function make(File $file): self
    {
        return new self($file);
    }

    public function build(): CreateFileDto
    {
        return new CreateFileDto([
            'file' => $this->file,
        ]);
    }
}
